MOD = 10**9 + 7

def numoffbt(arr, n):
    arr = sorted(arr)
    freq = {}
    for num in arr:
        freq[num] = freq.get(num, 0) + 1

    # Precompute all possible products and their counts
    product_counts = {}
    for x in arr:
        for y in arr:
            product = x * y
            product_counts[product] = product_counts.get(product, 0) + 1

    # Initialize DP: dp[x] = number of trees with root x
    dp = {}
    for x in arr:
        dp[x] = freq.get(x, 0)

    # We need to process in increasing order of x to ensure children are processed before parent
    # But since x can be up to 1e5 * 1e5, we need a smarter way
    # So we'll process all possible x in sorted order of arr and their products
    all_numbers = set(arr)
    for x in arr:
        all_numbers.add(x)
        for y in arr:
            all_numbers.add(x * y)

    sorted_numbers = sorted(all_numbers)

    for x in sorted_numbers:
        if x not in dp:
            dp[x] = 0
        # For each x, count all pairs (a, b) such that a*b = x
        count = 0
        for a in arr:
            if x % a != 0:
                continue
            b = x // a
            if b in freq:
                count += freq[a] * freq[b]
        # If x is in arr, we can also have single node trees
        if x in freq:
            dp[x] += freq[x]
        # Update dp[x] modulo MOD
        dp[x] %= MOD

    # The total number of trees is the sum of all dp[x] for x in arr
    total = 0
    for x in arr:
        total = (total + dp[x]) % MOD

    return total
